<?php

namespace Database\Seeders;

use App\Models\Genre;
use App\Models\Title;
use Illuminate\Database\Seeder;
use Illuminate\Support\Str;

class CatalogSeeder extends Seeder
{
    /**
     * مكتبة موسّعة: ٥٠ فيلم + ٢٥ مسلسل بتقييمات IMDb و Rotten Tomatoes الرسمية.
     * آمن للتكرار: ينشئ الناقص ويملأ الفارغ فقط (لا يمسح تعديلاتك).
     */
    public function run(): void
    {
        $posters = file_exists(__DIR__ . '/catalog_posters.php')
            ? require __DIR__ . '/catalog_posters.php'
            : [];

        foreach ($this->items() as $d) {
            $d['poster'] = $posters[$d['name']] ?? null;
            $title = Title::firstOrCreate(
                ['name' => $d['name']],
                [
                    'type' => $d['type'],
                    'description' => $d['desc'],
                    'release_year' => $d['year'],
                    'imdb_rating' => $d['imdb'],
                    'rt_rating' => $d['rt'],
                    'poster' => $d['poster'] ?? null,
                ],
            );

            $fill = [];
            if (blank($title->poster) && filled($d['poster'] ?? null)) {
                $fill['poster'] = $d['poster'];
            }
            if (is_null($title->imdb_rating)) {
                $fill['imdb_rating'] = $d['imdb'];
            }
            if (is_null($title->rt_rating)) {
                $fill['rt_rating'] = $d['rt'];
            }
            if (blank($title->description)) {
                $fill['description'] = $d['desc'];
            }
            if ($fill) {
                $title->update($fill);
            }

            $genreIds = collect($d['genres'])->map(fn (string $g) => Genre::firstOrCreate(
                ['name' => $g],
                ['slug' => Str::slug($g) ?: Str::random(8)],
            )->id)->all();

            $title->genres()->syncWithoutDetaching($genreIds);
            if (! $title->genre_id) {
                $title->update(['genre_id' => $genreIds[0] ?? null]);
            }
        }

        $this->command?->info('CatalogSeeder: تمت معالجة ' . count($this->items()) . ' عمل.');
    }

